//! The bundled GeoNames city and country index.
//!
//! `data/cities.tsv` and `data/countries.tsv` are generated by
//! `scripts/geonames-fetch.py` from the GeoNames free database; see
//! `data/SOURCE.md` for the dump checksums and the CC BY 4.0 attribution.
//! The index parses once and every lookup is pure — the same query always
//! returns the same answer.

use std::str::FromStr;
use std::sync::OnceLock;

use crate::suggest;
use chrono_tz::Tz;

/// A city in the bundled index. String fields borrow from the embedded data,
/// so they are valid for the life of the program.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct City {
    /// GeoNames display name.
    pub name: &'static str,
    /// ASCII-transliterated name.
    pub ascii_name: &'static str,
    /// ISO 3166-1 alpha-2 country code.
    pub country_code: &'static str,
    pub latitude: f64,
    pub longitude: f64,
    pub zone: Tz,
    pub population: u64,
}

/// A country in the bundled index, keyed by ISO code or name.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Country {
    pub iso2: &'static str,
    pub iso3: &'static str,
    pub name: &'static str,
}

/// A closest-match suggestion for an unresolved city query.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct CitySuggestion {
    pub name: &'static str,
    pub country_code: &'static str,
    pub latitude: f64,
    pub longitude: f64,
    /// Levenshtein distance from the query, lower is closer.
    pub distance: usize,
}

/// A closest-match suggestion for an unresolved country query.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct CountrySuggestion {
    pub name: &'static str,
    pub iso2: &'static str,
    /// Levenshtein distance from the query, lower is closer.
    pub distance: usize,
}

/// Lowercase and collapse whitespace — the same normalization the data-fetch
/// script applies to its sort keys, so queries and keys agree.
pub(crate) fn normalize(name: &str) -> String {
    name.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_lowercase()
}

pub(crate) struct Index {
    /// Cities in file order (sorted by ascii key, then country).
    pub(crate) cities: Vec<City>,
    /// (normalized key, offset into `cities`), sorted by key. A city answers
    /// to two keys — its display name and its ASCII name — when they differ.
    pub(crate) by_key: Vec<(String, u32)>,
    pub(crate) countries: Vec<Country>,
}

impl Index {
    /// The most populous city whose name matches `name` in `country_code`.
    pub(crate) fn city(&self, name: &str, country_code: &str) -> Option<City> {
        let query = normalize(name);
        self.candidates(&query)
            .filter(|city| city.country_code.eq_ignore_ascii_case(country_code))
            .max_by_key(|city| city.population)
    }

    /// The country matching an ISO 3166-1 alpha-2 or alpha-3 code or an
    /// English name, case-insensitively.
    pub(crate) fn country(&self, query: &str) -> Option<Country> {
        if query.trim().is_empty() {
            return None;
        }
        self.countries.iter().copied().find(|country| {
            country.iso2.eq_ignore_ascii_case(query)
                || country.iso3.eq_ignore_ascii_case(query)
                || normalize(country.name) == normalize(query)
        })
    }

    /// The closest cities to `query`, preferring the given country; falls
    /// back to a global search when the country holds no close match.
    pub(crate) fn closest_cities(
        &self,
        query: &str,
        country_code: Option<&str>,
        limit: usize,
    ) -> Vec<CitySuggestion> {
        let normalized = normalize(query);
        let mut suggestions = self.suggestions_in(&normalized, country_code, limit);
        if suggestions.is_empty() {
            suggestions = self.suggestions_in(&normalized, None, limit);
        }
        suggestions.truncate(limit);
        suggestions
    }

    fn suggestions_in(
        &self,
        query: &str,
        country_code: Option<&str>,
        limit: usize,
    ) -> Vec<CitySuggestion> {
        let mut ranked: Vec<(usize, u64, City)> = self
            .cities
            .iter()
            .copied()
            .filter(|city| {
                country_code.is_none_or(|code| city.country_code.eq_ignore_ascii_case(code))
            })
            .map(|city| {
                let distance = suggest::distance(query, normalize(city.ascii_name).as_str());
                (distance, city.population, city)
            })
            .collect();
        let limit = limit.min(ranked.len());
        ranked.select_nth_unstable_by_key(limit, |(distance, population, _)| {
            (*distance, std::cmp::Reverse(*population))
        });
        ranked
            .into_iter()
            .take(limit)
            .map(|(distance, _, city)| CitySuggestion {
                name: city.name,
                country_code: city.country_code,
                latitude: city.latitude,
                longitude: city.longitude,
                distance,
            })
            .collect()
    }

    /// The closest countries to `query`.
    pub(crate) fn closest_countries(&self, query: &str, limit: usize) -> Vec<CountrySuggestion> {
        let normalized = normalize(query);
        let mut ranked: Vec<(usize, Country)> = self
            .countries
            .iter()
            .map(|country| {
                (
                    suggest::distance(&normalized, &normalize(country.name)),
                    *country,
                )
            })
            .collect();
        let limit = limit.min(ranked.len());
        ranked.select_nth_unstable_by_key(limit, |(distance, _)| *distance);
        ranked
            .into_iter()
            .take(limit)
            .map(|(distance, country)| CountrySuggestion {
                name: country.name,
                iso2: country.iso2,
                distance,
            })
            .collect()
    }

    /// All cities answering to exactly `query` as a key.
    fn candidates<'a>(&'a self, query: &'a str) -> impl Iterator<Item = City> + 'a {
        let start = self.by_key.partition_point(|(key, _)| key.as_str() < query);
        self.by_key[start..]
            .iter()
            .take_while(move |(key, _)| key.as_str() == query)
            .filter_map(|(_, offset)| self.cities.get(*offset as usize).copied())
    }
}

static INDEX_CELL: OnceLock<Index> = OnceLock::new();

/// The process-wide bundled index, parsed on first use.
pub(crate) fn global() -> &'static Index {
    INDEX_CELL.get_or_init(parse_bundled)
}

fn parse_bundled() -> Index {
    const CITIES: &str = include_str!("../data/cities.tsv");
    const COUNTRIES: &str = include_str!("../data/countries.tsv");

    let mut cities = Vec::new();
    for row in CITIES.lines().filter(|line| !line.is_empty()) {
        let fields: Vec<&str> = row.split('\t').collect();
        if fields.len() != 7 {
            continue;
        }
        let (Some(latitude), Some(longitude)) = (fields[3].parse().ok(), fields[4].parse().ok())
        else {
            continue;
        };
        let (Some(population), Ok(zone)) = (fields[6].parse::<u64>().ok(), Tz::from_str(fields[5]))
        else {
            // A malformed row or a zone name the bundled tzdata does not
            // know: drop the row rather than guess a neighbor.
            continue;
        };
        cities.push(City {
            name: fields[0],
            ascii_name: fields[1],
            country_code: fields[2],
            latitude,
            longitude,
            zone,
            population,
        });
    }

    let mut by_key: Vec<(String, u32)> = cities
        .iter()
        .enumerate()
        .flat_map(|(offset, city)| {
            let offset = u32::try_from(offset).expect("invariant: fewer than 2^32 cities");
            [
                (normalize(city.ascii_name), offset),
                (normalize(city.name), offset),
            ]
        })
        .collect();
    by_key.sort();
    by_key.dedup();

    let mut countries = Vec::new();
    for row in COUNTRIES.lines().filter(|line| !line.is_empty()) {
        let fields: Vec<&str> = row.split('\t').collect();
        if fields.len() != 3 {
            continue;
        }
        countries.push(Country {
            iso2: fields[0],
            iso3: fields[1],
            name: fields[2],
        });
    }

    Index {
        cities,
        by_key,
        countries,
    }
}
